catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
  debugger;
  if (isLoading) {
    return;
  }

  g_form.hideFieldMsg("serial_number_form", true);
  if (newValue == "") {
    g_form.setValue("serial_dup_check", "");
    return;
  }
  g_form.setValue("serial_dup_check", "pending");

  var serial_number = g_form.getValue("serial_number_form");

  var ga = new GlideAjax("sn_disco_certmgmt.BNB_Verifica_Duplicidade_Certificado");
  ga.addParam("sysparm_name", "checkDuplicate");
  ga.addParam("sysparm_serial_number", serial_number);
  ga.getXMLAnswer(function (answer) {
    // Resposta antiga: o usuário já alterou o campo
    if (g_form.getValue("serial_number_form") != serial_number) {
      return;
    }
    try {
      var result = JSON.parse(answer);
      g_form.setValue("serial_dup_check", result.status);
      if (result.status == "OK") {
        if (result.formatted != serial_number) {
          g_form.setValue("serial_number_form", result.formatted);
        }
      } else {
        g_form.showFieldMsg("serial_number_form", result.message, "error");
      }
    } catch (e) {
      g_form.setValue("serial_dup_check", "ERROR");
      g_form.showFieldMsg(
        "serial_number_form",
        "Erro ao verificar duplicidade do Serial Number. " + e.message,
        "error",
      );
    }
  });
  return true;
}
